import { writeFile } from 'node:fs/promises';
import { clerkConfig } from '../dist/clerk-config.mjs';

const { publishableKey, enabled } = clerkConfig(process.env.CLERK_PUBLISHABLE_KEY || '');
if (process.env.GITHUB_ACTIONS === 'true' && publishableKey.startsWith('pk_test_')) {
  throw new Error('Use a production Clerk Publishable Key for the public GitHub Pages deployment.');
}
await writeFile(new URL('../dist/auth-config.mjs', import.meta.url),
  '// Generated by scripts/render-auth-config.mjs. Public configuration only.\n' +
  `export const clerkPublishableKey = ${JSON.stringify(publishableKey)};\n`);
console.log(enabled ? 'Clerk sign-in enabled.' : 'Clerk key is not configured; guest check-ins remain available.');
